alter table "Basic_Carrier_Record"."Aircraft_Holds" drop constraint "Aircraft_Holds_Name_check";
alter table "Basic_Carrier_Record"."Aircraft_Holds" add constraint "Aircraft_Holds_Name_check" check (((((btrim("Hold_Type")='BLK' and (btrim("Hold_Display_Name")=any(array['FWD','AFT','FLF','FLA','FLM','ALF','ALA','ALM','ALB']) or btrim("Hold_Display_Name") ~ '^[1-5]$')) or (btrim("Hold_Type")='ULD' and btrim("Hold_Display_Name") ~ '^[A-Z]{3}$')) and btrim("Hold_Name_ID")=upper(btrim("Hold_Deck_Location"))||':'||upper(btrim("Hold_Display_Name"))))) not valid;
update "Basic_Carrier_Record"."Aircraft_Holds" set "Hold_DOOR_Anchor_Type"='AREA',"Hold_DOOR_Anchor_Ref"=case btrim("Hold_Name_ID") when 'LOWER:1' then '1B' when 'LOWER:3' then '4B' end where "Carrier_IATA"='KA' and "Aircraft_Type_IATA"='738' and "Aircraft_Series_Subtype"='800' and btrim("Hold_Name_ID") in ('LOWER:1','LOWER:3');
